<template><div class="pagination"><button class="pagination-btn" :disabled="currentPage<=1" @click="$emit('change',currentPage-1)">＜</button><span class="pagination-info">{{currentPage}} / {{totalPages}}</span><button class="pagination-btn" :disabled="currentPage>=totalPages" @click="$emit('change',currentPage+1)">＞</button></div></template><script setup>defineProps({currentPage:Number,totalPages:Number});defineEmits(['change']);import './Pagination.css';</script>
